const raw = $input.first().json.syncCalendarId;
const isValid = typeof raw === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(raw);
return [{ json: {
  valid: isValid,
  syncCalendarId: isValid ? raw : null,
  ownerId: `sync-${$execution.id}-${Math.random().toString(36).slice(2, 10)}`,
} }];

const lease = $input.first().json;
const validated = $('Validate Input').first().json;
return [{ json: {
  syncCalendarId: validated.syncCalendarId,
  ownerId: validated.ownerId,
  googleCalendarId: lease.out_google_calendar_id,
  syncToken: lease.out_sync_token,
  pageToken: lease.out_pending_page_token,
  isFullSync: lease.out_needs_full_resync,
  pages: 0, applied: 0, tombstoned: 0, unknown: 0, malformed: 0, conflict: 0,
} }];

const s = $input.first().json;
const qs = { singleEvents: 'true' };
if (s.isFullSync) {
  // Baseline sync: deleted events are not needed yet (nothing to
  // detect a deletion against). showDeleted intentionally omitted
  // here (false) to avoid pulling an unbounded history of already-
  // cancelled events on the very first sync.
  qs.showDeleted = 'false';
  if (s.pageToken) qs.pageToken = s.pageToken;
} else {
  // Incremental sync: showDeleted must be requested explicitly so
  // deletions since the last sync token are actually returned --
  // Google does not guarantee tombstones appear in incremental
  // results otherwise.
  qs.syncToken = s.syncToken;
  qs.showDeleted = 'true';
  if (s.pageToken) qs.pageToken = s.pageToken;
}
return [{ json: { ...s, qs } }];

const resp = $input.first().json;
const s = $('Build Fetch Params').first().json;
const httpStatus = (resp.statusCode !== undefined) ? resp.statusCode : 'connection_error';
const httpOk = httpStatus === 200;
const bodyIsObject = httpOk && resp.body !== null && typeof resp.body === 'object' && !Array.isArray(resp.body);
const itemsIsArray = bodyIsObject && Array.isArray(resp.body.items);

function boundedToken(v) {
  return (v === undefined || v === null) ? null : ((typeof v === 'string' && v.length > 0 && v.length <= 2048) ? v : 'INVALID');
}

const rawNextPageToken = itemsIsArray ? boundedToken(resp.body.nextPageToken) : null;
const rawNextSyncToken = itemsIsArray ? boundedToken(resp.body.nextSyncToken) : null;
const tokensValid = rawNextPageToken !== 'INVALID' && rawNextSyncToken !== 'INVALID';
const itemCountValid = itemsIsArray ? resp.body.items.length <= 2500 : false;

const pageValid = httpOk && bodyIsObject && itemsIsArray && tokensValid && itemCountValid;

return [{ json: {
  ...s, httpStatus, httpOk, isGone: httpStatus === 410,
  pageValid,
  items: pageValid ? resp.body.items : [],
  nextPageToken: pageValid ? rawNextPageToken : null,
  nextSyncToken: pageValid ? rawNextSyncToken : null,
  isFinalPage: pageValid ? !rawNextPageToken : true,
} }];

const s = $input.first().json;
const reason = (s.httpOk && !s.pageValid) ? 'malformed_page_response' : 'http_error';
return [{ json: {
  status: 'calendar_error', httpStatus: s.httpStatus, reason,
  syncCalendarId: s.syncCalendarId, ownerId: s.ownerId,
} }];

const r = $input.first().json;
const s = $('Classify Fetch Result').first().json;
return [{ json: { status: 'aborted', reason: r.out_reason, syncCalendarId: s.syncCalendarId, ownerId: s.ownerId } }];

const r = $input.first().json;
const s = $('Classify Fetch Result').first().json;
return [{ json: {
  ...s,
  pages: s.pages + 1,
  applied: s.applied + r.out_applied_count,
  tombstoned: s.tombstoned + r.out_tombstoned_count,
  unknown: s.unknown + r.out_unknown_count,
  malformed: s.malformed + r.out_malformed_count,
  conflict: s.conflict + r.out_conflict_count,
  pageToken: s.nextPageToken,
} }];

const s = $('Init Page State').item.json;
const j = $json;
if (j.out_id === undefined) {
  return { json: { route: 'none', syncCalendarId: s.syncCalendarId, ownerId: s.ownerId, googleCalendarId: s.googleCalendarId } };
}
const op = j.out_operation;
let route;
if (op === 'create') route = 'create';
else if (op === 'update' || op === 'cancel') route = 'mutate';
else route = 'invalid_operation';
return { json: {
  route, syncCalendarId: s.syncCalendarId, ownerId: s.ownerId, googleCalendarId: s.googleCalendarId,
  outboxId: j.out_id, appointmentId: j.out_appointment_id, operation: op,
  idempotencyKey: j.out_idempotency_key, payload: j.out_payload,
  googleEventId: j.out_google_event_id, currentEtag: j.out_current_etag,
} };

const j = $json;
return { json: {
  outcome: 'failure', outboxId: j.outboxId, syncCalendarId: j.syncCalendarId, ownerId: j.ownerId,
  appointmentId: j.appointmentId, operation: j.operation,
  googleEventId: null, etag: null, updated: null, reason: 'invalid_outbox_operation', details: null,
} };

const resp = $json;
const j = $('Build Idempotency Check Request').item.json;
const httpStatus = (resp.statusCode !== undefined) ? resp.statusCode : 'connection_error';
const bodyOk = httpStatus === 200 && resp.body !== null && typeof resp.body === 'object' && !Array.isArray(resp.body) && Array.isArray(resp.body.items);
const checkFailed = !bodyOk;
const rawItems = bodyOk ? resp.body.items : [];

function isValidMatch(item) {
  if (!item || typeof item !== 'object') return false;
  const id = item.id;
  if (typeof id !== 'string' || id.length === 0 || id.length > 1024 || !/^[A-Za-z0-9_-]+$/.test(id)) return false;
  const priv = item.extendedProperties && item.extendedProperties.private;
  if (!priv || typeof priv !== 'object') return false;
  if (priv.appointmentId !== j.appointmentId) return false;
  if (priv.idempotencyKey !== j.idempotencyKey) return false;
  if (item.etag !== undefined && item.etag !== null && (typeof item.etag !== 'string' || item.etag.length > 512)) return false;
  return true;
}

let decision, matched = null;
if (checkFailed) {
  decision = 'lookup_failed';
} else if (rawItems.length === 0) {
  decision = 'no_match';
} else if (rawItems.length === 1) {
  const valid = isValidMatch(rawItems[0]);
  decision = valid ? 'single_valid_match' : 'mismatched_match';
  if (valid) matched = rawItems[0];
} else {
  decision = 'multiple_matches';
}

return { json: {
  ...j, decision,
  matchedEventId: matched ? matched.id : null,
  matchedEtag: (matched && typeof matched.etag === 'string' && matched.etag.length <= 512) ? matched.etag : null,
  matchedUpdated: (matched && typeof matched.updated === 'string' && matched.updated.length <= 64) ? matched.updated : null,
} };

const j = $json;
let reason;
if (j.decision === 'lookup_failed') reason = 'idempotency_lookup_failed';
else if (j.decision === 'multiple_matches') reason = 'multiple_idempotency_matches';
else reason = 'idempotency_marker_mismatch';
const outcome = j.decision === 'lookup_failed' ? 'failure' : 'conflict';
return { json: {
  outcome, outboxId: j.outboxId, syncCalendarId: j.syncCalendarId, ownerId: j.ownerId,
  appointmentId: j.appointmentId, operation: j.operation,
  googleEventId: null, etag: null, updated: null, reason, details: null,
} };

const j = $json;
return { json: {
  outcome: 'success', outboxId: j.outboxId, syncCalendarId: j.syncCalendarId, ownerId: j.ownerId,
  appointmentId: j.appointmentId, operation: j.operation,
  googleEventId: j.matchedEventId, etag: j.matchedEtag, updated: j.matchedUpdated, reason: null, details: null,
} };

const j = $json;
const body = { ...(j.payload || {}) };
body.extendedProperties = { private: { appointmentId: j.appointmentId, idempotencyKey: j.idempotencyKey } };
return { json: { ...j, body } };

const resp = $json;
const j = $('Build Create Request').item.json;
const httpStatus = (resp.statusCode !== undefined) ? resp.statusCode : 0;
if (httpStatus >= 200 && httpStatus < 300) {
  const e = resp.body || {};
  const idValid = typeof e.id === 'string' && e.id.length > 0 && e.id.length <= 1024 && /^[A-Za-z0-9_-]+$/.test(e.id);
  if (!idValid) {
    return { json: {
      outcome: 'failure', outboxId: j.outboxId, syncCalendarId: j.syncCalendarId, ownerId: j.ownerId,
      appointmentId: j.appointmentId, operation: j.operation,
      googleEventId: null, etag: null, updated: null, reason: 'invalid_created_event_id', details: null,
    } };
  }
  const etag = (typeof e.etag === 'string' && e.etag.length <= 512) ? e.etag : null;
  const updated = (typeof e.updated === 'string' && e.updated.length <= 64) ? e.updated : null;
  return { json: {
    outcome: 'success', outboxId: j.outboxId, syncCalendarId: j.syncCalendarId, ownerId: j.ownerId,
    appointmentId: j.appointmentId, operation: j.operation,
    googleEventId: e.id, etag, updated, reason: null, details: null,
  } };
}
return { json: {
  outcome: 'failure', outboxId: j.outboxId, syncCalendarId: j.syncCalendarId, ownerId: j.ownerId,
  appointmentId: j.appointmentId, operation: j.operation,
  googleEventId: null, etag: null, updated: null, reason: `http_${httpStatus}`, details: null,
} };

const j = $json;
const isCancel = j.operation === 'cancel';
const gid = j.googleEventId;
const gidValid = typeof gid === 'string' && gid.length > 0 && gid.length <= 1024 && /^[A-Za-z0-9_-]+$/.test(gid);
const etag = j.currentEtag;
const etagValid = typeof etag === 'string' && etag.length > 0 && etag.length <= 512;
let valid, invalidReason;
if (!gidValid) { valid = false; invalidReason = 'missing_or_invalid_event_id'; }
else if (!isCancel && !etagValid) { valid = false; invalidReason = 'missing_or_invalid_etag'; }
else { valid = true; invalidReason = null; }
return { json: {
  ...j,
  valid, invalidReason, isCancel,
  method: isCancel ? 'DELETE' : 'PATCH',
  body: isCancel ? {} : (j.payload || {}),
  headers: (gidValid && etagValid) ? { 'If-Match': etag } : {},
} };

const j = $json;
return { json: {
  outcome: 'conflict', outboxId: j.outboxId, syncCalendarId: j.syncCalendarId, ownerId: j.ownerId,
  appointmentId: j.appointmentId, operation: j.operation,
  googleEventId: null, etag: null, updated: null, reason: j.invalidReason, details: null,
} };

const resp = $json;
const j = $('Build Mutate Request').item.json;
const httpStatus = (resp.statusCode !== undefined) ? resp.statusCode : 0;

if (httpStatus === 410 && j.operation === 'cancel') {
  // Already cancelled/deleted on Calendar's side. Cancel is idempotent
  // BECAUSE this is explicitly handled as success -- not because a
  // repeat DELETE naturally returns an identical result (it doesn't;
  // a second DELETE on an already-cancelled event returns 410, tested
  // directly against the mock server's Google-accurate behavior).
  return { json: {
    outcome: 'success', outboxId: j.outboxId, syncCalendarId: j.syncCalendarId, ownerId: j.ownerId,
    appointmentId: j.appointmentId, operation: j.operation,
    googleEventId: j.googleEventId, etag: null, updated: null, reason: null, details: null,
  } };
}

if (httpStatus === 412) {
  return { json: {
    outcome: 'conflict', outboxId: j.outboxId, syncCalendarId: j.syncCalendarId, ownerId: j.ownerId,
    appointmentId: j.appointmentId, operation: j.operation,
    googleEventId: j.googleEventId, etag: null, updated: null,
    reason: 'etag_mismatch', details: { expected_etag_length: (j.currentEtag || '').length },
  } };
}
if ((httpStatus >= 200 && httpStatus < 300) || httpStatus === 204) {
  const e = resp.body || {};
  const etag = (typeof e.etag === 'string' && e.etag.length <= 512) ? e.etag : null;
  const updated = (typeof e.updated === 'string' && e.updated.length <= 64) ? e.updated : null;
  return { json: {
    outcome: 'success', outboxId: j.outboxId, syncCalendarId: j.syncCalendarId, ownerId: j.ownerId,
    appointmentId: j.appointmentId, operation: j.operation,
    googleEventId: j.googleEventId, etag, updated, reason: null, details: null,
  } };
}
return { json: {
  outcome: 'failure', outboxId: j.outboxId, syncCalendarId: j.syncCalendarId, ownerId: j.ownerId,
  appointmentId: j.appointmentId, operation: j.operation,
  googleEventId: null, etag: null, updated: null, reason: `http_${httpStatus}`, details: null,
} };

const s = $('Accumulate Counts').last() ? $('Accumulate Counts').last().json : $('Init Page State').first().json;
// The Postgres finalize node's own output replaces each item's json
// entirely (query columns only) -- the pre-finalize "outcome" this
// code needs was computed upstream by Classify Create/Mutate/Idempotency
// Result. Zip that list back up with the finalize node's out_ok by
// position: the Postgres node processes items 1:1, preserving order
// and count, so index-alignment is safe here.
let pre = [];
let post = [];
try { pre = $('Merge Finalize Inputs').all().map(i => i.json); } catch (e) { pre = []; }
try { post = $('Finalize Outbox Item').all().map(i => i.json); } catch (e) { post = []; }
const claimed = pre.length;
let applied = 0, conflicted = 0, failed = 0;
for (let idx = 0; idx < pre.length; idx++) {
  const outcome = pre[idx].outcome;
  const ok = post[idx] ? post[idx].out_ok : false;
  if (outcome === 'success' && ok) applied++;
  else if (outcome === 'conflict') conflicted++;
  else failed++;
}
return [{ json: {
  syncCalendarId: s.syncCalendarId, ownerId: s.ownerId,
  pull: { pages: s.pages, applied: s.applied, tombstoned: s.tombstoned, unknown: s.unknown, malformed: s.malformed, conflict: s.conflict },
  outbox: { claimed, applied, conflicted, failed },
} }];
